 65	    public ApiIndex getApi(APIName name, String sourcePath) throws FileNotFoundException, IOException {
 66	        ApiIndex ci = apis.get(name);
 67	        if (ci != null) return ci;
 68	        String s = apiFileName(name, sourcePath);
 69	
 70	        File f = new File(s);
 71	        if (!f.exists()) {
 72	            throw new FileNotFoundException(s);
 73	        }
 74	        Option<CompilationUnit> candidate = ASTIO.readJavaAst(s);
 75	        if (candidate.isNone()) {
 76	            throw new RepositoryError("Could not deserialize contents of repository file " + s);
 77	        }
 78	        ci = (ApiIndex)IndexBuilder.buildCompilationUnitIndex(candidate.unwrap(),
 79	                                                              f.lastModified(), true);
 80	        apis.put(name, ci);
 81	        return ci;
 82	    }
 83	
 84	    public ComponentIndex getComponent(APIName name, String sourcePath) throws FileNotFoundException, IOException {
 85	        ComponentIndex ci = components.get(name);
 86	        if (ci != null) return ci;
 87	        String s = compFileName(name, sourcePath);
 88	
 89	        File f = new File(s);
 90	        if (!f.exists()) {
 91	            throw new FileNotFoundException(s);
 92	        }
 93	        Option<CompilationUnit> candidate = ASTIO.readJavaAst(s);
 94	        if (candidate.isNone()) {
 95	            throw new RepositoryError("Could not deserialize contents of repository file " + s);
 96	        }
 97	        ci = (ComponentIndex)IndexBuilder.buildCompilationUnitIndex(candidate.unwrap(),
 98	                                                                    f.lastModified(), false);
 99	        components.put(name, ci);
100	        return ci;
101	
102	    }
