104	    public void addApi(APIName name, ApiIndex def, String sourcePath) {
105	        CompilationUnit ast = def.ast();
106	        checkName(name, ast);
107	
108	        Debug.debug(Debug.Type.REPOSITORY, 2, "Api ", name, " created at ", def.modifiedDate());
109	        apis.put(name, def);
110	
111	        try {
112	            ASTIO.writeJavaAst(ast, apiFileName(ast.getName(), sourcePath));
113	        }
114	        catch (IOException e) {
115	            throw new ShellException(e);
116	        }
117	    }
118	
119	    private void checkName(APIName name, CompilationUnit ast) throws RepositoryError {
120	        APIName actual = ast.getName();
121	        if (!actual.equals(name)) {
122	            //boolean flag = actual.equals(name);
123	            throw new RepositoryError(actual + " cannot be cached under name " + name);
124	        }
125	    }
126	
127	    public void addComponent(APIName name, ComponentIndex def, String sourcePath) {
128	        CompilationUnit ast = def.ast();
129	        checkName(name, ast);
130	        Debug.debug(Debug.Type.REPOSITORY, 2, "addComponent: Component ", name, " created at ", def.modifiedDate());
131	        // Cache component for quick retrieval.
132	        components.put(name, def);
133	
134	        try {
135	            ASTIO.writeJavaAst(ast, compFileName(ast.getName(), sourcePath));
136	        }
137	        catch (IOException e) {
138	            throw new ShellException(e);
139	        }
140	    }
141	
142	    public void deleteApi(APIName name) {
143	        apis.remove(name);
144	    }
145	
146	    public void deleteComponent(APIName name) {
147	        components.remove(name);
148	        SimpleClassLoader.reloadEnvironment(NodeUtil.nameString(name));
149	    }
