151	    private String compFileName(APIName name, String sourcePath) {
152	        return NamingCzar.cachedPathNameForCompAst(pwd, sourcePath, name);
153	    }
154	
155	    private String apiFileName(APIName name, String sourcePath) {
156	        return NamingCzar.cachedPathNameForApiAst(pwd, sourcePath, name);
157	    }
