159	    private long dateFromFile(APIName name, String s, String tag) throws FileNotFoundException {
160	        File f = new File(s);
161	        if (!f.exists()) throw new FileNotFoundException(tag + name.toString() + " (file " + s + ")");
162	        return f.lastModified();
163	    }
164	
165	    public long getModifiedDateForApi(ApiGraphNode node) throws FileNotFoundException {
166	        APIName name = node.getName();
167	        String sourcePath = node.getSourcePath();
168	        ApiIndex i = apis.get(name);
169	
170	        if (i != null) {
171	            Debug.debug(Debug.Type.REPOSITORY, 2, "Cached modified date for api ", name, " is ", i.modifiedDate());
172	            return i.modifiedDate();
173	        }
174	
175	        String s = apiFileName(name, sourcePath);
176	        String tag = "API ";
177	        return dateFromFile(name, s, tag);
178	    }
179	
180	    public long getModifiedDateForComponent(ComponentGraphNode node) throws FileNotFoundException {
181	        APIName name = node.getName();
182	        String sourcePath = node.getSourcePath();
183	
184	        ComponentIndex i = components.get(name);
185	        if (i != null) {
186	            Debug.debug(Debug.Type.REPOSITORY,
187	                        2,
188	                        "Cached modified date for component ",
189	                        name,
190	                        " is ",
191	                        i.modifiedDate());
192	            return i.modifiedDate();
193	        }
194	
195	        String s = compFileName(name, sourcePath);
196	        String tag = "Component ";
197	        return dateFromFile(name, s, tag);
198	    }
