526	    private class OutOfDateVisitor implements GraphVisitor<Boolean, FileNotFoundException> {
527	        // Rebuilds get triggered transitively across chains of API dependence.
528	        // "Youngest" is computed transitively.
529	        private Map<GraphNode, Long> youngestSourceDependedOn;
530	
531	        // Dates are not available for foreign imports.  Therefore, keep track
532	        // of a hashcode of the last-seen build, and if it does not match, then
533	        // assume stale.
534	        private Set<GraphNode> foreignChange;
535	
536	        // In a second pass, if anything is stale, or depends on stale, it is
537	        // marked for rebuild.
538	        private Map<GraphNode, Boolean> staleOrDependsOnStale;
539	
540	
541	        public OutOfDateVisitor() {
542	            youngestSourceDependedOn = new HashMap<GraphNode, Long>();
543	            staleOrDependsOnStale = new HashMap<GraphNode, Boolean>();
544	            foreignChange = new HashSet<GraphNode>();
545	        }
546	
547	        Fn<GraphNode, Boolean> outOfDateApi() {
548	            return new Fn<GraphNode, Boolean>() {
549	                @Override
550	                public Boolean apply(GraphNode g) {
551	                    return g instanceof ApiGraphNode && (staleOrDependsOnStale.get(g) ||
552	                                                         // TODO is this strictly necessary?
553	                                                         foreignJava.definesApi(((ApiGraphNode) g).getName()));
554	                }
555	            };
556	        }
