558	        Fn<GraphNode, Boolean> outOfDateComponent() {
559	            return new Fn<GraphNode, Boolean>() {
560	                @Override
561	                public Boolean apply(GraphNode g) {
562	                    return g instanceof ComponentGraphNode && staleOrDependsOnStale.get(g);
563	                }
564	            };
565	        }
