576	        private Long handle(GraphNode node) throws FileNotFoundException {
577	            if (youngestSourceDependedOn.containsKey(node)) {
578	                return youngestSourceDependedOn.get(node);
579	            }
580	            long youngest = node.getSourceDate();
581	            youngestSourceDependedOn.put(node, youngest);
582	
583	            List<GraphNode> depends = graph.depends(node);
584	            Debug.debug(Debug.Type.REPOSITORY, 2, node, " depends on ", depends);
585	            for (GraphNode next : depends) {
586	                if (foreignJava.definesApi(next)) {
587	                    // no date information here; need to look for the dependence
588	                    // info for this node.
589	                    if (foreignJava.dependenceChanged(node, next)) {
590	                        Debug.debug(Debug.Type.REPOSITORY, 1, "" + node + " added to foreign change by change in " + next);
591	                        foreignChange.add(node);
592	                    }
593	                }
594	
595	                long dependent_youngest = handle(next);
596	                if (dependent_youngest > youngest) {
597	
598	                    Debug.debug(Debug.Type.REPOSITORY, 3, next + " has younger source than " + node);
599	                    youngest = dependent_youngest;
600	                }
601	
602	            }
603	
604	            youngestSourceDependedOn.put(node, youngest);
605	
606	            return youngest;
607	        }
