612	            }
613	
614	            boolean stale1 = youngestSourceDependedOn.get(node) > getCacheDate(node);
615	            boolean stale2 = foreignChange.contains(node);
616	            boolean stale = stale1 || stale2;
617	            
618	            // If anything depended on has source that is younger than our compiled code,
