620	            if (stale) {
621	                if (stale1)
622	                    Debug.debug(Debug.Type.REPOSITORY,
623	                            1,
624	                            node,
625	                            " or dependent is newer ",
626	                            youngestSourceDependedOn.get(node),
627	                            " than the cache ",
628	                            getCacheDate(node));
629	                if (stale2)
630	                    Debug.debug(Debug.Type.REPOSITORY,
631	                            1,
632	                            node, " is in foreign change ", foreignChange);
633	                    
634	            }
635	
636	            staleOrDependsOnStale.put(node, stale);
637	
638	            List<GraphNode> depends = graph.depends(node);
